import{_ as t,l as o,o as e,c as i,v as n,p as E,x as l,d as s,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"电话会语气 NLP","description":"","frontmatter":{"title":"电话会语气 NLP","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/earnings-call-tone.md","filePath":"quant/earnings-call-tone.md","lastUpdated":1789023840000}'),p={name:"quant/earnings-call-tone.md"};function d(A,a,u,m,B,D){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=n('<h1 id="电话会语气-nlp" tabindex="-1">电话会语气 NLP <a class="header-anchor" href="#电话会语气-nlp" aria-label="Permalink to &quot;电话会语气 NLP&quot;">​</a></h1><div class="epigraph"><p>盈余电话会里管理层的用词与语音，含有超出当季数字本身的信息；把语气写成可复制的文本特征之前，必须先处理词典领域、问答轮次与时间戳，否则测到的是披露事件而不是语气。</p><footer>—— Mayew and Venkatachalam, The Power of Voice, Journal of Finance, 2012；Price, Doran, Peterson and Bliss, Journal of Banking &amp; Finance, 2012</footer></div><p>上市公司在季报后召开盈余电话会：先宣读准备好的稿，再接受分析师提问。Price、Doran、Peterson 与 Bliss 证明，电话会文本的语气对随后收益有增量解释力，超出盈余意外本身。Mayew 与 Venkatachalam 进一步用语音情感分析管理层的情感状态，并把它与未来业绩联系起来。这与 <a href="/quant/news-nlp-alpha">舆情文本</a> 同属公司披露的语言层，但语料更窄、结构更强：同一事件、可切分的准备稿与问答、可识别的发言人。Loughran 与 McDonald 的金融词典在这里仍然是测量的起点——通用情感词表会把「liability」一类词误判——Huang、Teoh 与 Zhang 则提醒「语气管理」：用词可以比基本面更积极，语气本身可能是操纵而不是信号。本篇写电话会语气作为量化特征：测什么、相对 <a href="/quant/pead-sue">SUE</a> 的增量、以及问答轮次为何往往比宣读稿更有信息。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>盈余数字已经进入价格的一条通道是 <a href="/quant/pead-sue">PEAD</a>：未预期盈余之后的漂移。电话会若还有增量，必须来自数字未写明的条件信息：展望的确定性、问答中的回避、语音里的紧张，或分析师问题的敌意。Li 对管理层讨论与分析（MD&amp;A）中前瞻语句的信息含量、Larcker 与 Zakolyukina 对电话会中欺骗性讨论的检测，都把「怎么说」从「说了什么数字」里分开。问题是测量。把整篇记录送进一个情感分数，会把宣读稿的公关语言与问答的即兴语言平均掉；用哈佛通用词表会把金融术语当成负面；用电话会当日的收益当标签训练监督模型，会把市场对数字的反应吸进词权，再在样本外当成「语气 alpha」。</p><p>时间戳同样关键。电话会通常在公告之后数小时内召开，价格在稿件与问答之间连续动。用全天收益回归会把公告跳与电话会信息混在一起。Price 等人的设计关心的是电话会文本相对盈余数字的增量；复制时必须把收益窗口对准会议结束之后，或至少把公告窗口分开报告。</p><h3 id="词典语气、语音与监督词权" tabindex="-1">词典语气、语音与监督词权 <a class="header-anchor" href="#词典语气、语音与监督词权" aria-label="Permalink to &quot;词典语气、语音与监督词权&quot;">​</a></h3><p>词典法：用 Loughran–McDonald 的正向、负向、不确定、弱模态等词表，在电话会文本上计词频，按文档长度标准化，得到净语气（正向减负向）或负面占比。优点是可审计、可跨年比较；缺点是无视否定、讽刺与领域新词。Price 等在电话会上展示了文本语气的增量。语音法：Mayew–Venkatachalam 用认知心理学与商业的情感计算工具，从管理层语音提取积极/消极情感状态，发现其与未来业绩相关，且分析师问题可以调节管理层的情感表达。监督法：用随后收益或意外作为标签学习词权，拟合强，但 Gentzkow、Kelly、Taddy 所总结的「文本即数据」警告仍然适用——词权不稳定、难解释、易吸入同期新闻。分层仍然正确：先词典与轮次结构，再把残差交给监督模型。</p><p><span class="marginnote">净语气 = 正向词减负向词，在电话会里经常接近公关稿的上限。真正有截面差异的往往是负面词与不确定词，或问答相对宣读稿的语气落差。只报一个「情感分」而不报分项与结构，无法与机制对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>切分。至少切成：准备好的管理层发言、分析师问题、管理层回答。特征可以是各段的 LM 负面占比、不确定词占比，以及「回答减宣读」的差分。差分捕捉的是即兴相对稿件的恶化或改善，Huang–Teoh–Zhang 的语气管理更常出现在可控的稿件里，问答是压力测试。发言人级：CEO 与 CFO 分开，Mayew 等的语音研究正是对人而不是对「公司平均声波」。分析师轮次：问题长度、是否追问、负面词，可作为信息需求的代理，而不是当作公司语气。</p><p>回归。截面上，控制 SUE、市值、账面市值、行业、上日收益与分析师修订，再看电话会特征对会议后窗口收益或未来盈余修正的系数。这与 Tetlock 等在新闻上的公司级设定平行，只是事件对齐到会议。重叠与换手：季频特征、持有到下一次会议，换手低于日频舆情，但仍集中在公告附近的价差扩大期，成本要按有效价差扣。监督模型必须按时间切分，不能把未来的电话会词汇分布用于过去的 IDF。</p><h3 id="语气管理、欺骗与「说得太好」" tabindex="-1">语气管理、欺骗与「说得太好」 <a class="header-anchor" href="#语气管理、欺骗与「说得太好」" aria-label="Permalink to &quot;语气管理、欺骗与「说得太好」&quot;">​</a></h3><p>Huang、Teoh、Zhang 定义语气管理为异常积极的用词，超出同期基本面所能解释的部分，并发现它与较差的未来业绩及相关的市场反应连在一起——语气可以是粉饰。Larcker 与 Zakolyukina 用语言线索（犹豫、极端正向、股东参考方式等）检测电话会中可能的欺骗性讨论，并对照后续的财务重述。对量化信号，这意味着：原始净正向不一定是利好；相对基本面回归后的残差正向，可能是风险。实务上应同时报告：原始 LM 分、相对 SUE 与会计变量的残差语气、问答减宣读的落差。三者同向时解释才稳；残差正向而 SUE 弱，更接近管理文献而不是动量。</p>',14)),(e(),E(h,null,{default:l(()=>[c(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Call%5B%22%E7%9B%88%E4%BD%99%E7%94%B5%E8%AF%9D%E4%BC%9A%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20Prep%5B%22%E5%AE%A3%E8%AF%BB%E7%A8%BF%22%5D%0A%20%20Call%20--%3E%20QA%5B%22%E9%97%AE%E7%AD%94%E8%BD%AE%E6%AC%A1%22%5D%0A%20%20Prep%20--%3E%20Dict%5B%22LM%20%E8%AF%8D%E5%85%B8%E8%AF%8D%E9%A2%91%22%5D%0A%20%20QA%20--%3E%20Dict%0A%20%20Voice%5B%22%E7%AE%A1%E7%90%86%E5%B1%82%E8%AF%AD%E9%9F%B3%E7%89%B9%E5%BE%81%22%5D%20--%3E%20Affect%5B%22%E6%83%85%E6%84%9F%E7%8A%B6%E6%80%81%22%5D%0A%20%20Dict%20--%3E%20Residual%5B%22%E7%9B%B8%E5%AF%B9%20SUE%20%E7%9A%84%E6%AE%8B%E5%B7%AE%E8%AF%AD%E6%B0%94%22%5D%0A%20%20Affect%20--%3E%20Residual%0A%20%20Residual%20--%3E%20Test%5B%22%E4%BC%9A%E8%AE%AE%E5%90%8E%E6%94%B6%E7%9B%8A%20%2F%20%E7%9B%88%E4%BD%99%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20SUE%5B%22%E7%9B%88%E4%BD%99%E6%84%8F%E5%A4%96%20SUE%22%5D%20--%3E%20Test%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息通道。管理层拥有尚未完全写入应计数字的内部信息，电话会的展望与措辞是廉价披露；市场对数字的即时反应不充分时，语气可以预测随后的修正与收益，这与 PEAD 的有限注意叙事相容。Price 等提供的是文本增量的证据；Mayew–Venkatachalam 提供的是语音情感与未来业绩的证据，机制更靠近「状态」而不是「用词策略」。</p><p>代理与粉饰。管理层有动机在稿件里偏正向（职业生涯、期权、分析师关系）。问答中分析师若施加压力，粉饰成本上升，真实状态更容易漏出来——这是为何结构切分重要。语气管理文献预测：异常正向之后是较差基本面，短期价格可能仍然被带动，随后反转。把电话会正向当持续多头信号，会在粉饰样本里符号接反。</p><p>语音与文本不是替代品。文本抓用词选择，语音抓难以完全控制的副语言。二者可以同向（真的乐观）或背离（稿件积极、声音紧张）。公开可复制研究仍以文本为主，因为语音数据的获取、说话人分离与工具许可更难；不能把 Mayew–Venkatachalam 的结论无条件接到某一种商业 API 的输出上而不做校验。</p><h3 id="分析师覆盖、语言与样本" tabindex="-1">分析师覆盖、语言与样本 <a class="header-anchor" href="#分析师覆盖、语言与样本" aria-label="Permalink to &quot;分析师覆盖、语言与样本&quot;">​</a></h3><p>电话会语气的截面主要存在于有会议记录、有足够分析师轮次的公司。小公司可能没有电话会，或记录不完整，因子会自动偏向大盘与高覆盖——必须对市值、覆盖中性，否则语气只是规模的代理。跨境样本还有语言与翻译：LM 词典为英文学 10-K 构建，直接用在翻译稿上会引入系统偏差。中文会议记录需要领域词表，不能假设英文负面词的译文仍是负面。这与舆情篇的跨语言警告相同，电话会因为高度公式化，翻译偏差可能更大而不是更小。</p><p><span class="marginnote">用大语言模型给每篇电话会打一个「情绪分」，若提示词含有事后新闻或未隔离的数字，分数会泄漏。要当量化特征，必须锁住模型版本、只输入会议文本、并报告相对 LM 词典的增量；否则无法区分模型记忆与语气测量。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>电话会不是随机样本：管理层可以选择是否召开、邀请谁提问、事后修订记录。存活与选择使「有会议」本身含信息。记录供应商的时间戳可能是入库时间而不是开说时间。语音特征对采样率、 overlapping 说话人与线路质量敏感，生产级复制成本高于词频。监督词权一旦用全市场收益训练，很难解释为公司特异信息。</p><p>与新闻舆情的分工：电话会是低频、高结构、与会计日历锁定的事件特征；新闻是高频、多源、需去重。二者不应加总成一个「文本因子」而不报告相关。增量检验的最低标准是：在控制 SUE 与公告窗收益之后，会议后窗口是否还有斜率。没有这条，所谓语气 alpha 只是盈余公告的另一个名字。出处上，文本增量以 Price 等（2012）与 LM 词典（2011）为测量基础，语音以 Mayew–Venkatachalam（2012）为准，粉饰与欺骗以 Huang–Teoh–Zhang（2014）与 Larcker–Zakolyukina（2012）为准。</p><p><span class="marginnote">把问答中的「下次再披露」当成负面语气，测到的可能是信息延迟而不是情感。应把不确定词、前瞻句与明确的业绩指引分开，否则词典分数会把合法的谨慎陈述写成利空。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>电话会语气是相对盈余数字的增量披露，测量须切分宣读与问答，并用金融领域词典。</li><li>Price 等证明文本语气的收益增量；Mayew–Venkatachalam 证明语音情感与未来业绩相关。</li><li>异常正向可能是语气管理而非利好；应报告相对 SUE 的残差语气，而不是单一情感分。</li><li>收益窗口要对准会议之后，并控制公告跳，否则因子只是 PEAD 的重包装。</li><li>出处：Mayew and Venkatachalam, <em>Journal of Finance</em>, 2012；Price, Doran, Peterson and Bliss, <em>JBF</em>, 2012；Loughran and McDonald, <em>Journal of Finance</em>, 2011；Huang, Teoh and Zhang, <em>The Accounting Review</em>, 2014；Larcker and Zakolyukina, <em>JAR</em>, 2012。</li></ul>',13))])}const f=t(p,[["render",d]]);export{k as __pageData,f as default};
